-- GoIngrid A1 topic-level theory and learning overview.
begin;
do $$ declare v_level_id uuid; v_module_id uuid; v_topic_id uuid; begin
select l.id into v_level_id from public.levels l where l.code='A1';
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=1;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=1;
update public.topics set learning_overview='{"title":"Tema 1","explanation_es":"Esta lección practica Spell your name mediante ejemplos, comprensión y producción guiada.","learning_outcomes":["El estudiante puede decir su nombre, pedir cómo se deletrea y confirmar una letra.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"clarify","meaning_es":"aclarar","example":"I need to clarify one letter."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=1;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=2;
update public.topics set learning_overview='{"title":"Tema 2","explanation_es":"I significa yo y se usa para hablar de uno mismo. You se usa para hablar directamente con otra persona o con varias personas. En inglés el pronombre normalmente aparece; no se omite como ocurre a menudo en español.","learning_outcomes":["El estudiante puede presentarse, preguntar el nombre de otra persona y mantener un intercambio inicial.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"everyone","meaning_es":"todos","example":"Everyone is here."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=1;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=3;
update public.topics set learning_overview='{"title":"Tema 3","explanation_es":"Am es la forma de to be que usamos con I. Podemos decir I am o la forma corta I''m. Se usa para identidad, origen, profesión y estados: I''m a student, I''m from Peru, I''m tired.","learning_outcomes":["El estudiante puede decir quién es y expresar estados básicos usando I am y I''m.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"meeting","meaning_es":"reunión","example":"The meeting is ready."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=1;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=4;
update public.topics set learning_overview='{"title":"Tema 4","explanation_es":"Usamos a antes de un sustantivo singular que comienza con sonido consonántico: a pen, a book. Usamos an antes de un sustantivo singular que comienza con sonido vocálico: an apple, an umbrella.","learning_outcomes":["El estudiante puede identificar y pedir un objeto singular usando a o an.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"shelf","meaning_es":"estante","example":"The bottle is on the shelf."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=1;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=5;
update public.topics set learning_overview='{"title":"Tema 5","explanation_es":"Un sustantivo singular habla de una cosa: one book. Para muchos sustantivos regulares añadimos -s: two books, three pens. El plural también cambia la forma del verbo: There is one book; There are two books.","learning_outcomes":["El estudiante puede distinguir un objeto de varios y formar plurales regulares básicos.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"missing","meaning_es":"que falta","example":"Two chairs are missing."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=1;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=6;
update public.topics set learning_overview='{"title":"Tema 6","explanation_es":"En inglés, el adjetivo normalmente va antes del sustantivo: a big room, a friendly teacher. También puede ir después de to be: The room is big. Los adjetivos no cambian por género ni plural: a small table, small tables.","learning_outcomes":["El estudiante puede describir personas y objetos con adjetivos básicos en frases sencillas.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"different","meaning_es":"diferente","example":"The bags are different."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=1;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=7;
update public.topics set learning_overview='{"title":"Tema 7","explanation_es":"My indica que algo pertenece a la persona que habla; your indica que pertenece a la persona a la que hablas. Van antes del sustantivo: my book, your phone. No cambian por singular o plural: my book, my books.","learning_outcomes":["El estudiante puede decir qué pertenece a sí mismo o a su interlocutor usando my y your.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"whose","meaning_es":"de quién","example":"Whose bag is this?"}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=1;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=8;
update public.topics set learning_overview='{"title":"Tema 8","explanation_es":"This señala un objeto singular cerca del hablante. That señala un objeto singular más lejos. Ambos pueden ir antes del sustantivo o funcionar solos: this phone, What is that?.","learning_outcomes":["El estudiante puede señalar y describir un objeto cercano o lejano usando this y that.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"nearby","meaning_es":"cercano","example":"The chairs are nearby."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=1;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=9;
update public.topics set learning_overview='{"title":"Tema 9","explanation_es":"There is presenta una cosa: There is a table. There are presenta varias: There are two chairs. La expresión describe qué existe o se encuentra en un lugar; no es igual que usar there como ubicación.","learning_outcomes":["El estudiante puede decir qué hay en un espacio usando there is y there are.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"ready","meaning_es":"listo / lista","example":"The room is ready."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=1;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=10;
update public.topics set learning_overview='{"title":"Tema 10","explanation_es":"In indica que algo está dentro de un espacio; on que está sobre una superficie; under que está debajo de algo. La preposición conecta el objeto con el lugar.","learning_outcomes":["El estudiante puede localizar objetos usando in, on y under.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"destination","meaning_es":"destino","example":"The room is your destination."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=2;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=1;
update public.topics set learning_overview='{"title":"Tema 1","explanation_es":"En una frase afirmativa básica, el orden habitual es sujeto + verbo + complemento: I study English. En inglés el sujeto normalmente debe aparecer, aunque en español pueda omitirse.","learning_outcomes":["El estudiante puede construir frases afirmativas básicas con sujeto, verbo y complemento.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"send","meaning_es":"enviar","example":"Send the message."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=2;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=2;
update public.topics set learning_overview='{"title":"Tema 2","explanation_es":"El presente simple describe hábitos y rutinas. Con I, you, we y they usamos la forma base: I work, they study. En preguntas usamos do: Do you work?","learning_outcomes":["El estudiante puede hablar de hábitos y rutinas usando el presente simple con I, you, we y they.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":[],"vocabulary":[{"term":"cook","meaning_es":"cocinar","example":"We cook at home."}],"pronunciation_targets":[],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=2;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=3;
update public.topics set learning_overview='{"title":"Tema 3","explanation_es":"Do ayuda a formar preguntas con I, you, we y they. Does se usa con he, she e it. El verbo principal permanece en forma base: Does he play?, no Does he plays?.","learning_outcomes":["El estudiante puede formular preguntas sobre hábitos usando do y does.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["Yes, I do.","No, I don''t.","Yes, she does.","No, she doesn''t.","Do you...?","Does he/she...?","Yes, he/she does.","No, he/she doesn''t."],"vocabulary":[{"term":"follow-up","meaning_es":"seguimiento","example":"Ask a follow-up question."},{"word":"read","meaning_es":"leer","example":"I read every night."},{"word":"watch TV","meaning_es":"ver televisión","example":"Does he watch TV?"},{"word":"go out","meaning_es":"salir","example":"We don''t go out on Mondays."},{"word":"exercise","meaning_es":"hacer ejercicio","example":"Do you exercise?"},{"word":"usually","meaning_es":"normalmente","example":"I usually read."},{"word":"short answer","meaning_es":"respuesta corta","example":"Yes, I do."},{"word":"wake up","meaning_es":"despertarse","example":"Do you wake up early?"},{"word":"work","meaning_es":"trabajar","example":"Does she work here?"},{"word":"study","meaning_es":"estudiar","example":"Do you study English?"},{"word":"like","meaning_es":"gustar","example":"Does he like music?"},{"word":"every day","meaning_es":"todos los días","example":"I study every day."}],"pronunciation_targets":[{"text":"Yes, I do.","focus":"unir I y do sin separar demasiado"},{"text":"No, she doesn''t.","focus":"marcar la contracción doesn''t"},{"text":"Do you study English every day?","focus":"reducir do you de forma natural"},{"text":"Does your brother study English too?","focus":"distinguir does y study"}],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=2;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=4;
update public.topics set learning_overview='{"title":"Tema 4","explanation_es":"Las palabras interrogativas piden información específica: what = qué/cuál, where = dónde y who = quién. En preguntas con presente simple usamos do/does: Where do you live? Who does she work with? Para preguntar por el verbo to be usamos su orden propio: What is your name?","learning_outcomes":["Formular y comprender preguntas básicas con what, where y who.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["What do you...?","Where do you...?","Who does he/she...?","When do you...?","Why do you...?","How do you...?","How often...?","What do you need?","Where is it?","Who is she?","When does it open?","Why are you here?"],"vocabulary":[{"word":"name","meaning_es":"nombre","example":"What is your name?"},{"word":"live","meaning_es":"vivir","example":"Where do you live?"},{"word":"work","meaning_es":"trabajar","example":"Where do you work?"},{"word":"friend","meaning_es":"amigo","example":"Who is your friend?"},{"word":"city","meaning_es":"ciudad","example":"What city do you live in?"},{"word":"address","meaning_es":"dirección","example":"What is your address?"},{"word":"start","meaning_es":"empezar","example":"When does the class start?"},{"word":"finish","meaning_es":"terminar","example":"When do you finish work?"},{"word":"because","meaning_es":"porque","example":"I study because I need English."},{"word":"early","meaning_es":"temprano","example":"Why do you wake up early?"},{"word":"get to","meaning_es":"llegar a","example":"How do you get to work?"},{"word":"often","meaning_es":"a menudo","example":"How often do you practice?"}],"pronunciation_targets":[{"text":"What is your name?","focus":"entonación ascendente y unión what is"},{"text":"Where do you live?","focus":"reducir do you sin perder claridad"},{"text":"Who is your friend?","focus":"mantener claro el sonido /h/"},{"text":"When does the class start?","focus":"does the como grupo de palabras"},{"text":"Why do you ask?","focus":"sonido /w/ inicial de why"},{"text":"How often do you practice?","focus":"ritmo de la pregunta completa"},{"text":"Excuse me. Where is room five?","focus":"entonación amable y enlace where is"},{"text":"When does it start?","focus":"does it como unidad"}],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=2;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=5;
update public.topics set learning_overview='{"title":"Tema 5","explanation_es":"Para negar acciones en presente simple usa sujeto + don''t + verbo base. Don''t es la contracción de do not. No agregues s al verbo después de don''t: I don''t drive, no I don''t drives. La negación va antes del verbo principal.","learning_outcomes":["Expresar hábitos y acciones que no realizas usando don''t con I, you, we y they.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["I don''t...","You don''t...","We don''t...","They don''t...","He doesn''t...","She doesn''t...","It doesn''t...","Don''t you...?","Doesn''t he/she...?","No, I don''t.","Yes, she does.","present simple affirmative and negative"],"vocabulary":[{"word":"drive","meaning_es":"conducir","example":"I don''t drive to work."},{"word":"drink coffee","meaning_es":"tomar café","example":"I don''t drink coffee."},{"word":"watch the news","meaning_es":"ver las noticias","example":"We don''t watch the news."},{"word":"work on Sundays","meaning_es":"trabajar los domingos","example":"They don''t work on Sundays."},{"word":"every morning","meaning_es":"cada mañana","example":"I exercise every morning."},{"word":"often","meaning_es":"a menudo","example":"We don''t often eat out."},{"word":"eat meat","meaning_es":"comer carne","example":"She doesn''t eat meat."},{"word":"like spicy food","meaning_es":"gustarle la comida picante","example":"He doesn''t like spicy food."},{"word":"use a car","meaning_es":"usar un automóvil","example":"She doesn''t use a car."},{"word":"sleep late","meaning_es":"dormir hasta tarde","example":"He doesn''t sleep late."},{"word":"need","meaning_es":"necesitar","example":"It doesn''t need batteries."},{"word":"usually","meaning_es":"normalmente","example":"She usually brings lunch."}],"pronunciation_targets":[{"text":"I don''t drive.","focus":"contracción don''t clara"},{"text":"We don''t work on Sundays.","focus":"ritmo de la negación"},{"text":"They don''t drink coffee either.","focus":"either al final"},{"text":"She doesn''t drive.","focus":"contracción doesn''t"},{"text":"He doesn''t eat meat.","focus":"enlace doesn''t eat"},{"text":"It doesn''t need batteries.","focus":"it y doesn''t claramente separados"},{"text":"Don''t you bring lunch?","focus":"unir don''t you y entonación"},{"text":"Doesn''t he work here?","focus":"contracción doesn''t"}],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=2;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=6;
update public.topics set learning_overview='{"title":"Tema 6","explanation_es":"Los adverbios de frecuencia indican cuántas veces ocurre algo: always, usually, often, sometimes y never. Forman una escala: always es 100% y never es 0%. La pregunta más común es How often do you...? y la respuesta puede ser un adverbio o una expresión como every day.","learning_outcomes":["Describir con qué frecuencia realizas actividades cotidianas usando adverbios básicos.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["always","usually","often","sometimes","never","subject + adverb + main verb","be + adverb","adverb at the beginning/end","every day","once a week","twice a month","three times a week"],"vocabulary":[{"word":"always","meaning_es":"siempre","example":"I always eat breakfast."},{"word":"usually","meaning_es":"normalmente","example":"I usually walk to work."},{"word":"often","meaning_es":"a menudo","example":"We often study together."},{"word":"sometimes","meaning_es":"a veces","example":"She sometimes cooks."},{"word":"never","meaning_es":"nunca","example":"They never smoke."},{"word":"practice","meaning_es":"practicar","example":"I practice often."},{"word":"be late","meaning_es":"llegar tarde/estar tarde","example":"I am never late."},{"word":"be tired","meaning_es":"estar cansado","example":"She is often tired."},{"word":"arrive","meaning_es":"llegar","example":"He usually arrives at eight."},{"word":"check email","meaning_es":"revisar el correo","example":"I always check my email."},{"word":"feel","meaning_es":"sentirse","example":"They sometimes feel tired."},{"word":"on time","meaning_es":"a tiempo","example":"We are always on time."}],"pronunciation_targets":[{"text":"I always practice in the morning.","focus":"always claramente reconocible"},{"text":"I sometimes study with Ana.","focus":"sílabas de sometimes"},{"text":"I never study alone.","focus":"never y ritmo de la frase"},{"text":"She is always on time.","focus":"unir is always"},{"text":"He usually arrives at eight.","focus":"usually y la s de arrives"},{"text":"I am never late.","focus":"am never con ritmo natural"},{"text":"three times a week","focus":"th de three y unión times a"},{"text":"once a week","focus":"once claramente, sin añadir sílabas"}],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=2;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=7;
update public.topics set learning_overview='{"title":"Tema 7","explanation_es":"Una buena conversación usa preguntas relacionadas. Empieza con información básica (what is your name?, where are you from?), continúa con hábitos (when do you study?, how do you spend your free time?) y añade una razón con why. La respuesta de una pregunta puede darte la siguiente pregunta.","learning_outcomes":["Usar preguntas interrogativas para obtener información personal y mantener una conversación conectada.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["What do you like?","Where are you from?","Who do you live with?","When do you study?","Why do you like it?","How do you spend your free time?","Where is...?","Where do I...?","When does...?","What time does...?","How do I...?","How much...?"],"vocabulary":[{"word":"interest","meaning_es":"interés","example":"What are your interests?"},{"word":"hobby","meaning_es":"pasatiempo","example":"What is your hobby?"},{"word":"favorite","meaning_es":"favorito","example":"What is your favorite movie?"},{"word":"spend time","meaning_es":"pasar tiempo","example":"How do you spend your free time?"},{"word":"together","meaning_es":"juntos","example":"Who do you study with?"},{"word":"because","meaning_es":"porque","example":"I like it because it is fun."},{"word":"entrance","meaning_es":"entrada","example":"Where is the entrance?"},{"word":"exit","meaning_es":"salida","example":"Where is the exit?"},{"word":"ticket","meaning_es":"boleto/entrada","example":"How much is a ticket?"},{"word":"schedule","meaning_es":"horario","example":"What time does it open?"},{"word":"floor","meaning_es":"piso","example":"What floor is the office on?"},{"word":"turn","meaning_es":"girar","example":"Where do I turn?"}],"pronunciation_targets":[{"text":"What do you do in your free time?","focus":"reducir do you y ritmo"},{"text":"Who do you live with?","focus":"who y enlace live with"},{"text":"When do you usually read?","focus":"when y usually"},{"text":"Where is the ticket office?","focus":"enlace where is"},{"text":"How much is it?","focus":"how much y entonación"},{"text":"What time does the train leave?","focus":"what time does y leave"},{"text":"What does this word mean?","focus":"does this y mean claramente"},{"text":"How do you spell it?","focus":"spell y entonación"}],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=2;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=8;
update public.topics set learning_overview='{"title":"Tema 8","explanation_es":"Los pronombres de objeto reciben la acción o aparecen después de una preposición: I call her, Help me, I talk to him. La tabla es: I → me, you → you, he → him, she → her, it → it, we → us, they → them. No uses el pronombre de sujeto después del verbo: Call me, no Call I.","learning_outcomes":["Usar pronombres de objeto para indicar quién recibe una acción.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["me","you","him","her","it","us","them","him/her for people","it for a thing or animal","us/them for groups","to + object pronoun","with me/you/him/her/us/them"],"vocabulary":[{"word":"call","meaning_es":"llamar","example":"Call me tonight."},{"word":"help","meaning_es":"ayudar","example":"Can you help me?"},{"word":"see","meaning_es":"ver","example":"I see her at work."},{"word":"know","meaning_es":"conocer/saber","example":"Do you know him?"},{"word":"invite","meaning_es":"invitar","example":"We invite them."},{"word":"meet","meaning_es":"encontrarse con","example":"I meet you at six."},{"word":"text","meaning_es":"enviar mensaje","example":"Text me later."},{"word":"show","meaning_es":"mostrar","example":"Can you show it to me?"},{"word":"give","meaning_es":"dar","example":"Give it to her."},{"word":"send","meaning_es":"enviar","example":"Send them a message."},{"word":"website","meaning_es":"sitio web","example":"I use it every day."},{"word":"dog","meaning_es":"perro","example":"I walk him every morning."}],"pronunciation_targets":[{"text":"Can you help me?","focus":"help me unido sin perder me"},{"text":"I know them.","focus":"them y sonido /ð/"},{"text":"Please call her.","focus":"her sin eliminar la h"},{"text":"Send it to me.","focus":"enlace send it to"},{"text":"Show it to her.","focus":"her con h audible"},{"text":"Send us a message.","focus":"us y ritmo"},{"text":"Wait for me.","focus":"for reducido y me claro"},{"text":"Come with us.","focus":"with y us"}],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=2;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=9;
update public.topics set learning_overview='{"title":"Tema 9","explanation_es":"Los sustantivos contables pueden tener un número: one apple, two apples. Tienen singular y plural y pueden usar a/an en singular. Los no contables se consideran una cantidad o sustancia: rice, water, bread, milk. No decimos a rice o two waters cuando hablamos de la sustancia; usamos some rice o a bottle of water.","learning_outcomes":["Distinguir sustantivos contables y no contables en situaciones cotidianas.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["a/an + singular countable","plural countable nouns","uncountable nouns without a/an","a piece of","a cup of","a glass of","a bottle of","a slice of","some + uncountable","How many...?","How much...?","a/an + countable singular"],"vocabulary":[{"word":"apple","meaning_es":"manzana","example":"I need an apple."},{"word":"egg","meaning_es":"huevo","example":"We need three eggs."},{"word":"rice","meaning_es":"arroz","example":"We need some rice."},{"word":"water","meaning_es":"agua","example":"There is some water."},{"word":"bread","meaning_es":"pan","example":"I buy bread."},{"word":"bottle","meaning_es":"botella","example":"I need two bottles."},{"word":"piece","meaning_es":"pedazo/pieza","example":"a piece of cake"},{"word":"cup","meaning_es":"taza","example":"a cup of rice"},{"word":"glass","meaning_es":"vaso","example":"a glass of water"},{"word":"slice","meaning_es":"rebanada","example":"two slices of bread"},{"word":"flour","meaning_es":"harina","example":"some flour"},{"word":"sugar","meaning_es":"azúcar","example":"a cup of sugar"}],"pronunciation_targets":[{"text":"three apples","focus":"plural /z/ o /s/ en apples"},{"text":"some rice","focus":"rice sin plural"},{"text":"a bottle of water","focus":"enlace bottle of water"},{"text":"two cups of rice","focus":"cups of como bloque"},{"text":"three glasses of water","focus":"plural glasses"},{"text":"two slices of bread","focus":"slices of y bread"},{"text":"How much rice do you need?","focus":"how much y rice"},{"text":"A packet of rice, please.","focus":"packet of como bloque"}],"lesson_count":4}'::jsonb where id=v_topic_id;
