update public.topics set learning_overview='{"title":"Tema 10","explanation_es":"Usa some en afirmaciones con plurales contables o no contables: some tomatoes, some cheese. Usa any normalmente en preguntas: Is there any juice? y en negaciones: There aren''t any onions. No significa ''cualquier'' en estos ejemplos; indica una cantidad no específica.","learning_outcomes":["Usar some y any para hablar de cantidades no específicas en afirmaciones, preguntas y negaciones.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["some + plural countable/uncountable","any in questions","any in negatives","not any","How much + uncountable noun","How many + plural countable noun","not much","not many","a lot of","a few + plural countable","few + plural countable","a little + uncountable"],"vocabulary":[{"word":"cheese","meaning_es":"queso","example":"There is some cheese."},{"word":"tomatoes","meaning_es":"tomates","example":"There are some tomatoes."},{"word":"juice","meaning_es":"jugo/zumo","example":"Is there any juice?"},{"word":"onions","meaning_es":"cebollas","example":"There aren''t any onions."},{"word":"left","meaning_es":"que queda","example":"Is there any food left?"},{"word":"fridge","meaning_es":"refrigerador","example":"Check the fridge."},{"word":"time","meaning_es":"tiempo","example":"How much time do we have?"},{"word":"homework","meaning_es":"tarea","example":"I have a lot of homework."},{"word":"questions","meaning_es":"preguntas","example":"How many questions are there?"},{"word":"money","meaning_es":"dinero","example":"I don''t have much money."},{"word":"people","meaning_es":"personas","example":"How many people are here?"},{"word":"a lot of","meaning_es":"mucho/a, muchos/as","example":"We have a lot of time."}],"pronunciation_targets":[{"text":"Is there any cheese?","focus":"any cheese unido"},{"text":"There is some juice.","focus":"some juice"},{"text":"There aren''t any onions.","focus":"aren''t any"},{"text":"How much time do we have?","focus":"much time y do we"},{"text":"How many questions are there?","focus":"many questions"},{"text":"There are a lot of questions.","focus":"a lot of como bloque"},{"text":"a few chairs","focus":"few chairs como bloque"},{"text":"a little water","focus":"little water"}],"lesson_count":4}'::jsonb where id=v_topic_id;
