update public.topics set learning_overview='{"title":"Tema 1","explanation_es":"Para presentarte puedes decir Hi, I''m + nombre o My name is + nombre. Para preguntar usas What''s your name? La expresión Nice to meet you equivale a ''mucho gusto'' y se responde Nice to meet you too. En una situación informal Hi es común; Hello funciona en situaciones informales y formales.","learning_outcomes":["Saludar, decir tu nombre y preguntar el nombre de otra persona.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["Hi, I''m...","My name is...","What''s your name?","Nice to meet you.","How are you?","Where are you from?","I''m from...","Where do you live?","I live in...","What do you do?","I work as...","I am ... years old"],"vocabulary":[{"word":"hello","meaning_es":"hola","example":"Hello, I''m Sofia."},{"word":"hi","meaning_es":"hola informal","example":"Hi, my name is Ben."},{"word":"name","meaning_es":"nombre","example":"What''s your name?"},{"word":"meet","meaning_es":"conocer/encontrarse","example":"Nice to meet you."},{"word":"nice","meaning_es":"agradable","example":"Nice to meet you."},{"word":"fine","meaning_es":"bien","example":"I''m fine, thanks."},{"word":"country","meaning_es":"país","example":"I''m from Colombia."},{"word":"city","meaning_es":"ciudad","example":"I live in Miami."},{"word":"live","meaning_es":"vivir","example":"Where do you live?"},{"word":"job","meaning_es":"trabajo","example":"What is your job?"},{"word":"phone number","meaning_es":"número de teléfono","example":"What''s your phone number?"},{"word":"email address","meaning_es":"dirección de correo","example":"What''s your email address?"}],"pronunciation_targets":[{"text":"Hi, I''m Sofia.","focus":"unir Hi I''m"},{"text":"What''s your name?","focus":"what''s y your"},{"text":"Nice to meet you too.","focus":"ritmo de la expresión fija"},{"text":"Where are you from?","focus":"where are you unido"},{"text":"I live in Chicago.","focus":"live in"},{"text":"What do you do?","focus":"repetición natural do you do"},{"text":"I am twenty-eight years old.","focus":"years old y número compuesto"},{"text":"I enjoy cooking.","focus":"enjoy y cooking"}],"lesson_count":4}'::jsonb where id=v_topic_id;
