update public.topics set learning_overview='{"title":"Tema 2","explanation_es":"Para presentar una persona usa This is my + familiar: This is my mother. Para varias personas usa These are my parents. Pregunta Who is this? para una persona y Who are they? para varias. My indica posesión: my mother, my brother, my family.","learning_outcomes":["Nombrar familiares y decir quiénes forman parte de tu familia.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["This is my...","These are my...","I have...","He/She is my...","Who is...?","He/She is...","He/She works...","He/She likes...","His/Her...","Who does he/she...?","I live with...","I visit..."],"vocabulary":[{"word":"mother","meaning_es":"madre","example":"This is my mother."},{"word":"father","meaning_es":"padre","example":"He is my father."},{"word":"sister","meaning_es":"hermana","example":"I have one sister."},{"word":"brother","meaning_es":"hermano","example":"These are my brothers."},{"word":"parents","meaning_es":"padres","example":"My parents live nearby."},{"word":"family","meaning_es":"familia","example":"My family is small."},{"word":"kind","meaning_es":"amable","example":"My sister is kind."},{"word":"funny","meaning_es":"divertido/a","example":"My brother is funny."},{"word":"quiet","meaning_es":"tranquilo/a","example":"My father is quiet."},{"word":"teacher","meaning_es":"profesor/a","example":"She works as a teacher."},{"word":"young","meaning_es":"joven","example":"My cousin is young."},{"word":"old","meaning_es":"mayor/viejo","example":"My grandfather is old."}],"pronunciation_targets":[{"text":"This is my mother.","focus":"this is my unido"},{"text":"These are my parents.","focus":"these y parents"},{"text":"Who are they?","focus":"who are y plural"},{"text":"Her name is Elena.","focus":"her name is"},{"text":"She works as a teacher.","focus":"s de works"},{"text":"What does she do?","focus":"does she do como bloque"},{"text":"I live with my wife and our daughter.","focus":"live with y our"},{"text":"We usually visit my parents.","focus":"usually visit"}],"lesson_count":4}'::jsonb where id=v_topic_id;
