update public.topics set learning_overview='{"title":"Tema 3","explanation_es":"Para presentar una habitación usa This is the + habitación o There is a + habitación. Para decir dónde haces algo usa in: sleep in the bedroom, cook in the kitchen. Where is...? pregunta la ubicación. Las expresiones next to y across the hallway ayudan a conectar habitaciones.","learning_outcomes":["Nombrar habitaciones y decir dónde ocurren actividades cotidianas.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["There is/are","This is the...","I sleep/cook/work in...","Where is...?","There is a...","There are...","The ... is on/in/under...","Where is my...?","I can''t find...","on","in","under"],"vocabulary":[{"word":"bedroom","meaning_es":"dormitorio","example":"I sleep in the bedroom."},{"word":"kitchen","meaning_es":"cocina","example":"We cook in the kitchen."},{"word":"bathroom","meaning_es":"baño","example":"The bathroom is upstairs."},{"word":"living room","meaning_es":"sala","example":"We watch TV in the living room."},{"word":"dining room","meaning_es":"comedor","example":"We eat in the dining room."},{"word":"hallway","meaning_es":"pasillo","example":"The hallway is narrow."},{"word":"table","meaning_es":"mesa","example":"The book is on the table."},{"word":"chair","meaning_es":"silla","example":"There are four chairs."},{"word":"sofa","meaning_es":"sofá","example":"The keys are on the sofa."},{"word":"lamp","meaning_es":"lámpara","example":"The lamp is next to the bed."},{"word":"mirror","meaning_es":"espejo","example":"The mirror is in the bathroom."},{"word":"keys","meaning_es":"llaves","example":"I can''t find my keys."}],"pronunciation_targets":[{"text":"This is the living room.","focus":"living room como bloque"},{"text":"Where is the kitchen?","focus":"where is the kitchen"},{"text":"I sleep in the bedroom.","focus":"sleep in y bedroom"},{"text":"Where are my keys?","focus":"where are y keys"},{"text":"I can''t find them.","focus":"can''t y them"},{"text":"They are under the sofa.","focus":"under the sofa"},{"text":"The passport is behind the books.","focus":"behind the books"},{"text":"It is between two books.","focus":"between two"}],"lesson_count":4}'::jsonb where id=v_topic_id;
