update public.topics set learning_overview='{"title":"Tema 4","explanation_es":"Para narrar una rutina usa el presente simple y conectores de orden: first, then, after that y finally. Wake up es despertarse y get up es levantarse; no son exactamente lo mismo. Have breakfast es la expresión natural para desayunar. Puedes preguntar What do you do next? para continuar la secuencia.","learning_outcomes":["Describir las actividades principales de un día en orden.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["I wake up","I get up","I have breakfast","I go to work/school","then/after that/finally","I start/finish at...","I work/study from... to...","at noon","in the afternoon/evening","What time...?","on weekdays","on weekends"],"vocabulary":[{"word":"wake up","meaning_es":"despertarse","example":"I wake up at seven."},{"word":"get up","meaning_es":"levantarse","example":"I get up after my alarm."},{"word":"take a shower","meaning_es":"ducharse","example":"I take a shower in the morning."},{"word":"get dressed","meaning_es":"vestirse","example":"I get dressed quickly."},{"word":"have breakfast","meaning_es":"desayunar","example":"I have breakfast at home."},{"word":"leave home","meaning_es":"salir de casa","example":"I leave home at eight."},{"word":"start work","meaning_es":"empezar a trabajar","example":"I start work at nine."},{"word":"finish work","meaning_es":"terminar de trabajar","example":"I finish work at five."},{"word":"have lunch","meaning_es":"almorzar","example":"We have lunch at noon."},{"word":"go home","meaning_es":"ir a casa","example":"I go home at six."},{"word":"make dinner","meaning_es":"preparar la cena","example":"She makes dinner."},{"word":"go to bed","meaning_es":"acostarse","example":"I go to bed at ten."}],"pronunciation_targets":[{"text":"I wake up at six thirty.","focus":"wake up y hora"},{"text":"I take a shower and get dressed.","focus":"take a shower/get dressed"},{"text":"I leave home at eight.","focus":"leave home"},{"text":"I start work at nine and finish at five.","focus":"start/finish y horas"},{"text":"I have lunch at noon.","focus":"lunch at noon"},{"text":"I go to bed at ten.","focus":"go to bed"},{"text":"What do you do on weekdays?","focus":"on weekdays"},{"text":"I usually wake up early.","focus":"usually wake up"}],"lesson_count":4}'::jsonb where id=v_topic_id;
