update public.topics set learning_overview='{"title":"Tema 5","explanation_es":"Para preferencias usa like o don''t like + sustantivo: I like fruit; I don''t like fish. Pregunta Do you like...? y responde Yes, I do o No, I don''t. Food puede hablar de comida en general; para una preferencia concreta usa My favorite food is.... No necesitas traducir literalmente los artículos del español.","learning_outcomes":["Nombrar alimentos y bebidas y decir qué te gusta o no te gusta.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["I like...","I don''t like...","My favorite food is...","Do you like...?","Yes, I do/No, I don''t","I''d like...","Can I have...?","How much is/are...?","How many...?","Here you are/Thank you","For me...","Anything else?"],"vocabulary":[{"word":"breakfast","meaning_es":"desayuno","example":"I eat fruit for breakfast."},{"word":"lunch","meaning_es":"almuerzo","example":"I have lunch at noon."},{"word":"dinner","meaning_es":"cena","example":"We cook dinner at home."},{"word":"fruit","meaning_es":"fruta","example":"I like fruit."},{"word":"vegetables","meaning_es":"verduras","example":"She eats vegetables."},{"word":"coffee","meaning_es":"café","example":"Do you like coffee?"},{"word":"I''d like","meaning_es":"quisiera","example":"I''d like a kilo of apples."},{"word":"fresh","meaning_es":"fresco/a","example":"Are these vegetables fresh?"},{"word":"price","meaning_es":"precio","example":"What''s the price?"},{"word":"kilo","meaning_es":"kilo","example":"A kilo, please."},{"word":"receipt","meaning_es":"recibo","example":"Can I have a receipt?"},{"word":"change","meaning_es":"cambio","example":"Here is your change."}],"pronunciation_targets":[{"text":"I like rice and vegetables.","focus":"like rice and"},{"text":"I don''t like fish.","focus":"don''t like"},{"text":"Do you like spicy food?","focus":"do you like"},{"text":"I''d like a kilo of apples, please.","focus":"I''d like y kilo of"},{"text":"Can I have two bottles of water?","focus":"can I have"},{"text":"How much are the apples?","focus":"much are"},{"text":"I''d like the chicken with rice, please.","focus":"I''d like y chicken with rice"},{"text":"Can I have some water, please?","focus":"can I have y please"}],"lesson_count":4}'::jsonb where id=v_topic_id;
