update public.topics set learning_overview='{"title":"Tema 6","explanation_es":"Para preguntar la hora usa What time is it? y responde It''s + hora. O''clock significa ''en punto''; half past = y media; a quarter past = y cuarto; a quarter to = menos cuarto. Para citas usa at + hora: meet at four o''clock. En conversaciones internacionales también es común decir three thirty o four fifteen.","learning_outcomes":["Preguntar y decir la hora en situaciones cotidianas.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["What time is it?","It''s...","at + time","o''clock","half past","quarter past/to","What day is it?","What date is it?","on Monday","in July","My birthday is on...","ordinal dates"],"vocabulary":[{"word":"o''clock","meaning_es":"en punto","example":"It is three o''clock."},{"word":"half past","meaning_es":"y media","example":"It is half past six."},{"word":"quarter past","meaning_es":"y cuarto","example":"It is a quarter past two."},{"word":"quarter to","meaning_es":"menos cuarto","example":"It is a quarter to five."},{"word":"morning","meaning_es":"mañana","example":"The class is in the morning."},{"word":"evening","meaning_es":"tarde/noche","example":"The meeting is in the evening."},{"word":"Monday","meaning_es":"lunes","example":"The class is on Monday."},{"word":"Friday","meaning_es":"viernes","example":"We meet on Friday."},{"word":"January","meaning_es":"enero","example":"My birthday is in January."},{"word":"July","meaning_es":"julio","example":"The trip is in July."},{"word":"birthday","meaning_es":"cumpleaños","example":"When is your birthday?"},{"word":"appointment","meaning_es":"cita","example":"I have an appointment."}],"pronunciation_targets":[{"text":"What time is it?","focus":"what time is it"},{"text":"It''s half past three.","focus":"half past"},{"text":"Let''s meet at four o''clock.","focus":"meet at y o''clock"},{"text":"The class is on Monday.","focus":"on Monday"},{"text":"My birthday is in July.","focus":"birthday y in July"},{"text":"July twenty-first","focus":"ordinal twenty-first"},{"text":"Are you free on Thursday?","focus":"free on Thursday"},{"text":"How about Friday at three?","focus":"how about y at three"}],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=3;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=7;
update public.topics set learning_overview='{"title":"Tema 7","explanation_es":"Para preguntar por la existencia de un lugar usa Is there a...? o Are there any...? Para ubicarlo usa The bank is near the station. Las expresiones near, next to y across from describen relaciones entre lugares. Downtown significa en el centro de la ciudad.","learning_outcomes":["Nombrar lugares comunes de una ciudad y decir dónde están.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["There is/are","The ... is near/next to...","Where is...?","I go to the...","How do I get to...?","go straight","turn left/right","at the corner","on your left/right","How can I get to...?","Which bus/train...?","Take the..."],"vocabulary":[{"word":"bank","meaning_es":"banco","example":"The bank is near the station."},{"word":"supermarket","meaning_es":"supermercado","example":"I go to the supermarket."},{"word":"pharmacy","meaning_es":"farmacia","example":"The pharmacy is next to the bank."},{"word":"hospital","meaning_es":"hospital","example":"The hospital is on Main Street."},{"word":"library","meaning_es":"biblioteca","example":"There is a library downtown."},{"word":"park","meaning_es":"parque","example":"We walk in the park."},{"word":"go straight","meaning_es":"seguir derecho","example":"Go straight for two blocks."},{"word":"turn left","meaning_es":"girar a la izquierda","example":"Turn left at the corner."},{"word":"turn right","meaning_es":"girar a la derecha","example":"Turn right after the bank."},{"word":"corner","meaning_es":"esquina","example":"The cafe is on the corner."},{"word":"block","meaning_es":"cuadra","example":"Walk two blocks."},{"word":"crosswalk","meaning_es":"paso de peatones","example":"Use the crosswalk."}],"pronunciation_targets":[{"text":"Is there a supermarket near here?","focus":"is there y near here"},{"text":"The pharmacy is next to the bank.","focus":"pharmacy y next to"},{"text":"It is across from the park.","focus":"across from"},{"text":"How do I get to the train station?","focus":"how do I get to"},{"text":"Go straight for two blocks.","focus":"straight y blocks"},{"text":"Turn right at the bank.","focus":"turn right"},{"text":"How can I get to the museum?","focus":"how can I get to"},{"text":"Take the number five bus.","focus":"number five bus"}],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=3;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=8;
update public.topics set learning_overview='{"title":"Tema 8","explanation_es":"Para hablar de un plan cercano usa I am going to + destino: I am going to Boston. Para el medio de transporte usa travel by train/plane/bus. Pregunta Where are you going?, When are you leaving? y What time is your flight/train?. Passport y suitcase son objetos importantes del viaje.","learning_outcomes":["Hablar de un viaje básico, destino, transporte y equipaje.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["I am going to...","I am traveling by...","I have...","Where are you going?","When are you leaving?","Where is...?","Which platform/gate...?","What time does it leave?","I need...","Is this...?","I have a reservation","My name is..."],"vocabulary":[{"word":"trip","meaning_es":"viaje","example":"I am planning a trip."},{"word":"destination","meaning_es":"destino","example":"My destination is Boston."},{"word":"flight","meaning_es":"vuelo","example":"My flight is at ten."},{"word":"train","meaning_es":"tren","example":"I am traveling by train."},{"word":"suitcase","meaning_es":"maleta","example":"My suitcase is small."},{"word":"passport","meaning_es":"pasaporte","example":"I have my passport."},{"word":"departure","meaning_es":"salida","example":"The departure is at ten."},{"word":"arrival","meaning_es":"llegada","example":"What time is the arrival?"},{"word":"platform","meaning_es":"andén","example":"The train leaves from platform three."},{"word":"gate","meaning_es":"puerta de embarque","example":"Where is gate five?"},{"word":"ticket","meaning_es":"billete/boleto","example":"I need a ticket to Boston."},{"word":"luggage","meaning_es":"equipaje","example":"Where can I leave my luggage?"}],"pronunciation_targets":[{"text":"I am going to Boston.","focus":"going to Boston"},{"text":"I am traveling by train.","focus":"traveling by train"},{"text":"I am leaving on Friday morning.","focus":"leaving on Friday"},{"text":"Where is platform three?","focus":"platform three"},{"text":"What time does the train leave?","focus":"does the train leave"},{"text":"Do I need a ticket?","focus":"do I need"},{"text":"I have a reservation.","focus":"have a reservation"},{"text":"What floor is my room on?","focus":"floor y room on"}],"lesson_count":4}'::jsonb where id=v_topic_id;
