select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=9;
update public.topics set learning_overview='{"title":"Tema 9","explanation_es":"Para preguntar por trabajo usa What do you do? y responde I am a teacher o I work as an engineer. Work in puede indicar un tipo de lugar o área: work in an office; work at puede indicar una institución o lugar concreto: work at a school. Do you like your job? pregunta si te gusta tu empleo.","learning_outcomes":["Decir a qué te dedicas, dónde trabajas y qué haces durante el día.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["What do you do?","I am a...","I work as...","I work in/at...","I like my job","I study...","I am taking a course","I have class on...","I study at...","What are you studying?","I need to...","I have to..."],"vocabulary":[{"word":"job","meaning_es":"trabajo/empleo","example":"I like my job."},{"word":"office","meaning_es":"oficina","example":"I work in an office."},{"word":"store","meaning_es":"tienda","example":"She works at a store."},{"word":"teacher","meaning_es":"profesor/a","example":"My teacher is kind."},{"word":"nurse","meaning_es":"enfermero/a","example":"She works as a nurse."},{"word":"engineer","meaning_es":"ingeniero/a","example":"I am an engineer."},{"word":"course","meaning_es":"curso","example":"I am taking an English course."},{"word":"class","meaning_es":"clase","example":"I have class on Tuesday."},{"word":"subject","meaning_es":"materia","example":"English is my favorite subject."},{"word":"student","meaning_es":"estudiante","example":"I am a student."},{"word":"homework","meaning_es":"tarea","example":"I do my homework at night."},{"word":"task","meaning_es":"tarea","example":"I have a task for today."}],"pronunciation_targets":[{"text":"What do you do?","focus":"pregunta fija de profesión"},{"text":"I work as an engineer.","focus":"work as an engineer"},{"text":"I work at a school.","focus":"work at a school"},{"text":"I am taking an English course.","focus":"taking an English course"},{"text":"I have class on Tuesday and Thursday.","focus":"days and class"},{"text":"I do my homework at night.","focus":"do my homework"},{"text":"What are you working on?","focus":"working on"},{"text":"Can you send me the file?","focus":"send me the file"}],"lesson_count":4}'::jsonb where id=v_topic_id;
select m.id into v_module_id from public.modules m where m.level_id=v_level_id and m.sort_order=3;
select t.id into v_topic_id from public.topics t where t.module_id=v_module_id and t.sort_order=10;
update public.topics set learning_overview='{"title":"Tema 10","explanation_es":"Comienza con Excuse me y pide ayuda con Can you help me? o Could you help me?. Explica la necesidad con I need help with + cosa o actividad. Para buscar un lugar pregunta Where can I find...? y cierra con Thank you for your help. Could suena más cortés; Can es muy común y directo.","learning_outcomes":["Pedir ayuda y explicar una necesidad básica con cortesía.","Comprender ejemplos y reconocer el lenguaje en contexto.","Usar lo aprendido en una situación comunicativa."],"key_language":["Excuse me","Can you help me?","Could you help me?","I need help with...","Where can I...?","Thank you","I need...","I need to...","I don''t have...","Can I...?","Do you have...?","Here you are"],"vocabulary":[{"word":"help","meaning_es":"ayuda/ayudar","example":"Can you help me?"},{"word":"find","meaning_es":"encontrar","example":"I need help finding my bag."},{"word":"understand","meaning_es":"entender","example":"I understand now."},{"word":"information","meaning_es":"información","example":"I need some information."},{"word":"explain","meaning_es":"explicar","example":"Let me explain the problem."},{"word":"problem","meaning_es":"problema","example":"I have a problem."},{"word":"water","meaning_es":"agua","example":"I need some water."},{"word":"medicine","meaning_es":"medicina","example":"I need medicine."},{"word":"phone charger","meaning_es":"cargador de teléfono","example":"Do you have a phone charger?"},{"word":"ticket","meaning_es":"billete/entrada","example":"I need a ticket."},{"word":"restroom","meaning_es":"baño","example":"Where is the restroom?"},{"word":"urgent","meaning_es":"urgente","example":"This is urgent."}],"pronunciation_targets":[{"text":"Excuse me. Can you help me?","focus":"excuse me y help me"},{"text":"I need some information.","focus":"need some information"},{"text":"Thank you for your help.","focus":"thank you for your help"},{"text":"I need a ticket to Boston.","focus":"need a ticket to"},{"text":"I also need a phone charger.","focus":"phone charger"},{"text":"Can I pay by card?","focus":"pay by card"},{"text":"I am lost. I need help.","focus":"lost y need help"},{"text":"My phone is broken.","focus":"phone is broken"}],"lesson_count":4}'::jsonb where id=v_topic_id;
end $$;
